  external int source;

  /// Whether `uncertainty_seconds` is meaningful.
  @ffi.Uint8()
  external int hasUncertainty;

  /// Reserved, zero.
  @ffi.Array(2)
  external ffi.Array<ffi.Uint8> reserved;

  /// TT less UT1, seconds.
  /// Unit: s. Example: 63.83.
  @ffi.Double()
  external double seconds;

  /// The one-sigma uncertainty, seconds, when `has_uncertainty`.
  /// Unit: s. Example: 0.0.
  @ffi.Double()
  external double uncertaintySeconds;

