  /// The locale; lent until the next call on the context.
  external ffi.Pointer<ffi.Char> locale;

  /// The file's SHA-256 as sixty-four hex digits; lent until the next
  /// call on the context.
  external ffi.Pointer<ffi.Char> sha256;

}

