/// The bytes of a blob the library filled, copied out and the blob
/// freed, so nothing of the library's outlives the call.
Uint8List _takeBlob(TeistroLibrary lib, ffi.Pointer<BlobStruct> blob) {
  final bytes = Uint8List.fromList(blob.ref.data.asTypedList(blob.ref.len));
  lib.ts_blob_free(blob);
  return bytes;
}

/// The text of a string the library allocated, copied and the string freed.
String _takeString(TeistroLibrary lib, ffi.Pointer<StringStruct> string) {
  final text = string.ref.data == ffi.nullptr
      ? ''
      : string.ref.data.cast<pkg_ffi.Utf8>().toDartString();
  lib.ts_string_free(string);
  return text;
}

/// The text of a string the library lent, copied before the next call
/// replaces it.
String _takeStr(ffi.Pointer<StrStruct> str) => str.ref.data == ffi.nullptr
    ? ''
    : str.ref.data.cast<pkg_ffi.Utf8>().toDartString();

/// The library every context and static call was opened with, so a
/// finaliser can find the symbol it frees with.
TeistroLibrary? _library;

/// Remembers the open library.
void rememberLibrary(TeistroLibrary lib) {
  _library ??= lib;
}

